//! Cryptography for mvchat: the group secret, per-pair keys, AEAD for voice and MACs for
//! the punch packets, plus the anti-replay window.
//!
//! - The group secret (32 bytes) is generated by the server part once per server session and
//!   handed out in the `mvchat:roster` payload; the game channel is already encrypted.
//! - The pair key of two participants (canonical order, both sides derive the same):
//!   `pair_key = SHA256(secret || le_bytes(min(uuid_a, uuid_b)) || le_bytes(max(uuid_a, uuid_b)))`
//! - VOICE bodies are ChaCha20-Poly1305 ciphertext; the nonce is 12 bytes
//!   `0x00 x4 || counter_be(u64)` from the packet header, and the 28-byte header is the AAD.
//! - PING/PONG/ASK/ECHO bodies are an 8-byte truncated Poly1305 tag over the header (plus the
//!   reported address for ECHO), computed as the tag of an empty ChaCha20-Poly1305 message
//!   under the pair key with a zero nonce.
//! - Replay protection: a sliding 64-packet window per peer; packets with a counter at or
//!   below the highest seen outside the window are dropped.

use chacha20poly1305::aead::{Aead, Payload};
use chacha20poly1305::{ChaCha20Poly1305, Key, KeyInit, Nonce};
use sha2::{Digest, Sha256};

use crate::engine::protocol::{HEADER_LEN, Header, write_header};

/// Size of the group secret and of every pair key.
pub const KEY_LEN: usize = 32;
/// Truncated MAC length on control packets.
pub const MAC_LEN: usize = 8;
/// AEAD tag length.
pub const TAG_LEN: usize = 16;
/// Replay window size in packets.
pub const REPLAY_WINDOW: u64 = 64;

/// Derives the pair key of `a` and `b` from the group secret. Symmetric in `a`/`b`.
pub fn pair_key(secret: &[u8; KEY_LEN], a: u128, b: u128) -> [u8; KEY_LEN] {
    let (min, max) = if a <= b { (a, b) } else { (b, a) };
    let mut hasher = Sha256::new();
    hasher.update(secret);
    hasher.update(min.to_le_bytes());
    hasher.update(max.to_le_bytes());
    let mut out = [0u8; KEY_LEN];
    out.copy_from_slice(&hasher.finalize());
    out
}

fn cipher(key: &[u8; KEY_LEN]) -> ChaCha20Poly1305 {
    ChaCha20Poly1305::new(Key::from_slice(key))
}

/// The key that MACs ASK/ECHO punch traffic between a client and the server's punch socket
/// (the socket is not a participant, so there is no pair key for it).
pub fn punch_key(secret: &[u8; KEY_LEN]) -> [u8; KEY_LEN] {
    let mut hasher = Sha256::new();
    hasher.update(secret);
    hasher.update(b"mvchat:punch");
    let mut out = [0u8; KEY_LEN];
    out.copy_from_slice(&hasher.finalize());
    out
}

/// The AEAD nonce for a packet: 4 zero bytes then the header's counter, big-endian.
pub fn nonce_from_counter(counter: u64) -> [u8; 12] {
    let mut nonce = [0u8; 12];
    nonce[4..].copy_from_slice(&counter.to_be_bytes());
    nonce
}

fn header_bytes(header: &Header) -> [u8; HEADER_LEN] {
    let mut v = Vec::with_capacity(HEADER_LEN);
    write_header(&mut v, header);
    let mut out = [0u8; HEADER_LEN];
    out.copy_from_slice(&v);
    out
}

/// Seals a VOICE body: AEAD over `plaintext` (pose + Opus frame) with the header as AAD.
/// Returns ciphertext + 16-byte tag.
pub fn seal_voice(key: &[u8; KEY_LEN], header: &Header, plaintext: &[u8]) -> Vec<u8> {
    let aad = header_bytes(header);
    cipher(key)
        .encrypt(
            Nonce::from_slice(&nonce_from_counter(header.counter)),
            Payload {
                msg: plaintext,
                aad: &aad,
            },
        )
        .expect("ChaCha20-Poly1305 encryption of a bounded body cannot fail")
}

/// Opens a VOICE body; `None` when the tag does not verify (wrong key, tampered, replayed
/// into a fresh counter is caught by the replay window instead).
pub fn open_voice(key: &[u8; KEY_LEN], header: &Header, ciphertext: &[u8]) -> Option<Vec<u8>> {
    if ciphertext.len() < TAG_LEN {
        return None;
    }
    let aad = header_bytes(header);
    cipher(key)
        .decrypt(
            Nonce::from_slice(&nonce_from_counter(header.counter)),
            Payload {
                msg: ciphertext,
                aad: &aad,
            },
        )
        .ok()
}

/// The 8-byte truncated MAC of a control packet over its header and optional extra bytes
/// (the address an ECHO reports).
pub fn mac8(key: &[u8; KEY_LEN], header: &Header, extra: &[u8]) -> [u8; MAC_LEN] {
    let aad = header_bytes(header);
    let mut full_aad = aad.to_vec();
    full_aad.extend_from_slice(extra);
    let tag = cipher(key)
        .encrypt(
            Nonce::from_slice(&[0u8; 12]),
            Payload {
                msg: &[],
                aad: &full_aad,
            },
        )
        .expect("empty-message encryption cannot fail");
    let mut out = [0u8; MAC_LEN];
    out.copy_from_slice(&tag[..MAC_LEN]);
    out
}

/// Verifies a control packet's MAC by recomputing it and comparing in constant time.
pub fn verify_mac8(key: &[u8; KEY_LEN], header: &Header, extra: &[u8], mac: &[u8]) -> bool {
    if mac.len() != MAC_LEN {
        return false;
    }
    let expected = mac8(key, header, extra);
    let mut diff = 0u8;
    for (a, b) in expected.iter().zip(mac.iter()) {
        diff |= a ^ b;
    }
    diff == 0
}

/// Sliding anti-replay window of [`REPLAY_WINDOW`] packets.
#[derive(Clone, Debug)]
pub struct ReplayWindow {
    highest: u64,
    mask: u64,
    init: bool,
}

impl Default for ReplayWindow {
    fn default() -> Self {
        Self::new()
    }
}

impl ReplayWindow {
    pub fn new() -> Self {
        Self {
            highest: 0,
            mask: 0,
            init: false,
        }
    }
    /// `true` when `counter` is fresh and is now recorded; `false` for a replay or a packet
    /// too far behind the window.
    pub fn check_and_update(&mut self, counter: u64) -> bool {
        if !self.init {
            self.init = true;
            self.highest = counter;
            self.mask = 1;
            return true;
        }
        if counter > self.highest {
            let shift = counter - self.highest;
            self.mask = if shift >= REPLAY_WINDOW {
                0
            } else {
                self.mask << shift
            };
            self.highest = counter;
            self.mask |= 1;
            true
        } else {
            let diff = self.highest - counter;
            if diff >= REPLAY_WINDOW {
                return false;
            }
            let bit = 1u64 << diff;
            if self.mask & bit != 0 {
                return false;
            }
            self.mask |= bit;
            true
        }
    }
}

/// Fills `out` with OS entropy (CSPRNG). Native: the platform's CSPRNG (`/dev/urandom` on
/// unix, `BCryptGenRandom` on Windows). The wasm sandbox has no entropy source, so there the
/// bytes are a SHA-256 KDF over time and addresses — acceptable only because the wasm variant
/// is a relay skeleton whose server side runs on a native host in practice.
pub fn fill_random(out: &mut [u8]) {
    fill_random_platform(out);
}

#[cfg(unix)]
fn fill_random_platform(out: &mut [u8]) {
    use std::io::Read;
    if let Ok(mut f) = std::fs::File::open("/dev/urandom")
        && f.read_exact(out).is_ok()
    {
        return;
    }
    fill_random_fallback(out);
}

#[cfg(windows)]
fn fill_random_platform(out: &mut [u8]) {
    #[link(name = "bcrypt")]
    extern "system" {
        fn BCryptGenRandom(
            algorithm: *mut core::ffi::c_void,
            buffer: *mut u8,
            length: u32,
            flags: u32,
        ) -> i32;
    }
    const BCRYPT_USE_SYSTEM_PREFERRED_RNG: u32 = 0x0000_0002;
    // SAFETY: `out` is a valid buffer of `out.len()` bytes; the call fills it with CSPRNG bytes.
    let status = unsafe {
        BCryptGenRandom(
            core::ptr::null_mut(),
            out.as_mut_ptr(),
            out.len() as u32,
            BCRYPT_USE_SYSTEM_PREFERRED_RNG,
        )
    };
    if status >= 0 {
        return;
    }
    fill_random_fallback(out);
}

#[cfg(not(any(unix, windows)))]
fn fill_random_platform(out: &mut [u8]) {
    fill_random_fallback(out);
}

fn fill_random_fallback(out: &mut [u8]) {
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::time::{SystemTime, UNIX_EPOCH};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let mut hasher = Sha256::new();
    hasher.update(nanos.to_le_bytes());
    hasher.update(COUNTER.fetch_add(1, Ordering::Relaxed).to_le_bytes());
    hasher.update((fill_random_fallback as *const () as usize).to_le_bytes());
    hasher.update((out.len() as u64).to_le_bytes());
    let seed = hasher.finalize();
    let mut block = seed.to_vec();
    let mut written = 0;
    while written < out.len() {
        let mut hasher = Sha256::new();
        hasher.update(&block);
        hasher.update(written.to_le_bytes());
        block = hasher.finalize().to_vec();
        let take = (out.len() - written).min(block.len());
        out[written..written + take].copy_from_slice(&block[..take]);
        written += take;
    }
}

/// Generates a fresh 32-byte group secret.
pub fn generate_secret() -> [u8; KEY_LEN] {
    let mut secret = [0u8; KEY_LEN];
    fill_random(&mut secret);
    secret
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::protocol::PacketType;

    fn header(sender: u128, counter: u64, kind: PacketType) -> Header {
        Header {
            sender,
            counter,
            kind,
        }
    }

    #[test]
    fn pair_key_is_symmetric_and_secret_dependent() {
        let secret = generate_secret();
        let a = 0xAAAA_u128;
        let b = 0xBBBB_u128;
        assert_eq!(pair_key(&secret, a, b), pair_key(&secret, b, a));
        let other = generate_secret();
        assert_ne!(pair_key(&secret, a, b), pair_key(&other, a, b));
        assert_ne!(pair_key(&secret, a, b), pair_key(&secret, a, a));
    }

    #[test]
    fn voice_seal_open_round_trip() {
        let secret = generate_secret();
        let key = pair_key(&secret, 1, 2);
        let h = header(1, 7, PacketType::Voice);
        let plain = b"pose-and-opus-frame";
        let ct = seal_voice(&key, &h, plain);
        assert_eq!(ct.len(), plain.len() + TAG_LEN);
        assert_eq!(open_voice(&key, &h, &ct).as_deref(), Some(plain.as_slice()));
    }

    #[test]
    fn voice_open_rejects_tampering_and_wrong_key_and_wrong_counter() {
        let secret = generate_secret();
        let key = pair_key(&secret, 1, 2);
        let h = header(1, 7, PacketType::Voice);
        let ct = seal_voice(&key, &h, b"hello");
        let mut tampered = ct.clone();
        tampered[0] ^= 1;
        assert!(open_voice(&key, &h, &tampered).is_none());
        let wrong = pair_key(&secret, 1, 3);
        assert!(open_voice(&wrong, &h, &ct).is_none());
        let other_counter = header(1, 8, PacketType::Voice);
        assert!(open_voice(&key, &other_counter, &ct).is_none());
        assert!(open_voice(&key, &h, &ct[..TAG_LEN - 1]).is_none());
    }

    #[test]
    fn mac8_verifies_and_rejects() {
        let secret = generate_secret();
        let key = pair_key(&secret, 5, 9);
        let h = header(5, 3, PacketType::Ask);
        let mac = mac8(&key, &h, b"");
        assert!(verify_mac8(&key, &h, b"", &mac));
        assert!(!verify_mac8(&key, &h, b"x", &mac));
        assert!(!verify_mac8(
            &key,
            &header(5, 4, PacketType::Ask),
            b"",
            &mac
        ));
        assert!(!verify_mac8(&pair_key(&secret, 5, 10), &h, b"", &mac));
        assert!(!verify_mac8(&key, &h, b"", &[0u8; MAC_LEN]));
        assert!(!verify_mac8(&key, &h, b"", &[0u8; MAC_LEN - 1]));
    }

    #[test]
    fn replay_window_accepts_fresh_rejects_old_and_dupes() {
        let mut w = ReplayWindow::new();
        assert!(w.check_and_update(1));
        assert!(w.check_and_update(2));
        assert!(w.check_and_update(70)); // gap > window: window slides fully
        assert!(!w.check_and_update(1)); // too old
        assert!(!w.check_and_update(70)); // duplicate
        assert!(w.check_and_update(71));
        assert!(w.check_and_update(69)); // inside the window, not seen
        assert!(!w.check_and_update(69)); // now a duplicate
        let mut w2 = ReplayWindow::new();
        for c in (37..=100u64).rev() {
            assert!(w2.check_and_update(c));
        }
        assert!(!w2.check_and_update(36)); // 64 behind the window edge
        assert!(!w2.check_and_update(100)); // duplicate
        assert!(w2.check_and_update(101));
    }

    #[test]
    fn nonce_is_counter_derived() {
        let n = nonce_from_counter(0x0102_0304_0506_0708);
        assert_eq!(&n[..4], &[0, 0, 0, 0]);
        assert_eq!(&n[4..], &0x0102_0304_0506_0708u64.to_be_bytes());
    }

    #[test]
    fn random_is_not_constant() {
        let a = generate_secret();
        let b = generate_secret();
        assert_ne!(a, b);
        assert_ne!(a, [0u8; 32]);
    }
}
